    message E2ControlRequest {
     optional near_rt_ric_apis_common_ies.v2.ProcedureTransactionId procedure_transaction_id = 1;
     optional near_rt_ric_apis_common_ies.v2.GlobalE2NodeId global_e2_node_id = 2;
     optional near_rt_ric_apis_common_ies.v2.RanFunctionId ran_function_id = 3; 
     optional e2_related_apis_common_ies.v1.E2CallProcessId e2_call_process_id = 4; 
